import asyncio
R="us-east-1"
async def safe(tag,**kw):
    try:
        await call_boto3(**kw); return (tag,"ok")
    except Exception as e: return (tag,f"ERR {str(e)[:150]}")

async def main():
    sgs={"task":"sg-0ae82bd3c34221dd6","alb":"sg-069b61cbd5598662d","db":"sg-06d50aa3eb52a80b4"}
    out=[]
    for name,sg in list(sgs.items()):
        try:
            d=await call_boto3(service_name="ec2",operation_name="DescribeSecurityGroups",region_name=R,params={"GroupIds":[sg]})
        except Exception as e:
            out.append((f"describe-{name}", f"gone/{str(e)[:60]}")); continue
        g=d["SecurityGroups"][0]
        if g.get("IpPermissions"):
            out.append(await safe(f"revoke-in-{name}", service_name="ec2", operation_name="RevokeSecurityGroupIngress", region_name=R,
                params={"GroupId":sg,"IpPermissions":g["IpPermissions"]}))
        if g.get("IpPermissionsEgress"):
            out.append(await safe(f"revoke-out-{name}", service_name="ec2", operation_name="RevokeSecurityGroupEgress", region_name=R,
                params={"GroupId":sg,"IpPermissions":g["IpPermissionsEgress"]}))
    for attempt in range(8):
        rem={}
        for name,sg in sgs.items():
            r=await safe(f"del-sg-{name}", service_name="ec2", operation_name="DeleteSecurityGroup", region_name=R, params={"GroupId":sg})
            if r[1]=="ok" or "NotFound" in r[1]:
                out.append((r[0],"ok"))
            else:
                rem[name]=sg
                if attempt>=7: out.append((r[0],r[1]))
        sgs=rem
        if not sgs: break
        await asyncio.sleep(15)
    return {"log":out,"undeleted":sgs}
